<script lang="ts">import {onMount} from 'svelte';import {subscribeAudio,cancelAudio,clearAudioStatus,type AudioStatus} from '../audio/service';let state=$state<AudioStatus>({active:false,phase:'idle',message:''});onMount(()=>subscribeAudio(value=>state=value));</script>
{#if state.phase!=='idle'}<aside class="transcription-toast" role="status" aria-live="polite"><div><strong>{state.active?(state.phase==='install'?'Загрузка модели':'Локальная расшифровка'):state.phase==='error'?'Обработка остановлена':'Готово'}</strong><span>{state.message}</span>{#if state.active&&state.progress!==undefined}<progress max="100" value={state.progress}></progress>{/if}</div><button aria-label={state.active?'Отменить обработку':'Скрыть уведомление'} onclick={state.active?cancelAudio:clearAudioStatus}>{state.active?'Отмена':'×'}</button></aside>{/if}
<style>.transcription-toast{position:fixed;z-index:300;bottom:calc(140px + env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);display:flex;align-items:center;gap:12px;width:min(380px,calc(100vw - 32px));padding:12px 14px;border-radius:20px;border:1px solid var(--theme-border);background:var(--theme-surface);color:var(--theme-text);box-shadow:0 8px 30px #0002}.transcription-toast>div{display:grid;gap:5px;min-width:0;flex:1}strong{font-size:12px}span{font-size:11px;color:var(--theme-muted);overflow:hidden;text-overflow:ellipsis;white-space:nowrap}button{font-size:12px;padding:4px 8px;border:0;background:transparent;min-height:36px}progress{width:100%;height:3px;accent-color:var(--theme-accent)}</style>
